%[text] # 未知周期干扰的主动悬架鲁棒性与性能分析（Jafari, Ioannou,et al. 2015）
%%
%[text] ## 1 被控系统建模
%[text] 考虑以下三阶模型：$G\_0(z) = \\frac{-0.00146(z - 0.1438)(z - 1)}{(z - 0.7096)(z^2 - 0.04369z + 0.01392)}$
%[text] 离线设计控制器理论上能够完全拒绝干扰的周期性部分：
%[text] -  $d\_s${"editStyle":"visual"} 是幅度为1的单频正弦信号，$v${"editStyle":"visual"} 是均值为零、标准差为0.02且 $|v| \\leq 0.1$ 的高斯噪声。
%[text] - 采样周期 $T\_s = 1/480 \\text{sec}\n$ \
clear; close all; clc;
addpath('..\functions');
% 离散系统G0(z)
Ts = 1/480;
z = tf('z');
fs = 1/Ts;
G0 = (-0.00146*(z-0.1438)*(z-1)) / ((z - 0.7096)*(z^2 - 0.04369*z + 0.01392));

% 计算灵敏度函数和互补灵敏度函数
% 假设单位反馈: S = 1/(1+G0), T = G0/(1+G0)
S = feedback(1, G0);  % 灵敏度函数 S = 1/(1+G0)
T = feedback(G0, 1);  % 互补灵敏度函数 T = G0/(1+G0)

% 计算频率响应
[H_G0, f_bode] = freqz(G0.num{1}, G0.den{1}, 1000, fs);
[H_S, ~] = freqz(S.num{1}, S.den{1}, 1000, fs);
[H_T, ~] = freqz(T.num{1}, T.den{1}, 1000, fs);

% 绘制三个传递函数的幅频响应
figure; hold on;  %[output:249a68d7]
semilogx(f_bode, 20*log10(abs(H_G0)), 'b-', 'LineWidth', 1.5, 'DisplayName', 'G_0(z) 开环传函'); %[output:249a68d7]
semilogx(f_bode, 20*log10(abs(H_S)), 'r-', 'LineWidth', 1.5, 'DisplayName', 'S(z) 灵敏度函数'); %[output:249a68d7]
semilogx(f_bode, 20*log10(abs(H_T)), 'g--', 'LineWidth', 1.5, 'DisplayName', 'T(z) 互补灵敏度函数'); %[output:249a68d7]
xlabel('频率 (Hz)'); %[output:249a68d7]
ylabel('幅值 (dB)'); %[output:249a68d7]
title('开环传函G_0(z)与灵敏度函数S(z), T(z)的幅频响应'); %[output:249a68d7]
legend('Location', 'best'); grid on; %[output:249a68d7]
xlim([f_bode(2), f_bode(end)]); % 避免DC点的显示问题 %[output:249a68d7]
%%
%[text] ## 2 求解准备
w_interp = 0.0521; % interpolation frequencies (rad)
N = 15;
nf = length(w_interp);
z_interp = exp(1j * w_interp);

% frequency grid for Hinf constraints
Nfreq = 1000;                     
w_grid = linspace(0, pi, Nfreq);
z_grid = exp(1j*w_grid);
% precompute frequency responses
G_grid = squeeze(freqresp(G0, w_grid * fs)).';        % rad/sample → rad/s
G_interp = squeeze(freqresp(G0, w_interp * fs)).';   % rad/sample → rad/s
% build Phi matrices
Phi_grid = zeros(Nfreq, N);
Phi_interp = zeros(nf, N);
for k = 1:N
    Phi_grid(:,k)   = z_grid .^ (-(k-1));      % 修正：标准 z^{-(k-1)} 基
    Phi_interp(:,k) = z_interp .^ (-(k-1));   % 修正：标准 z^{-(k-1)} 基
end

% build interpolation A * theta = b (complex)
A = diag(G_interp) * Phi_interp; % size N x N (complex)
b = ones(size(G_interp));        % complex ones

% if theta real, convert to real linear eqns
Aeq = [ real(A); imag(A) ];
beq = [ real(b)'; imag(b)' ];

% ---------- 可行性检查（先看是否存在满足等式的 theta） ----------
feasible_flag = true;
% 线性可行性：是否有 theta s.t. Aeq * theta = beq
% 简单尝试解方程并测残差
theta_test = Aeq \ beq;
resnorm = norm(Aeq*theta_test - beq);
fprintf('线性可行性检验: 等式最小残差 = %.3e\n', resnorm); %[output:11582b8f]
if resnorm > 1e-8
    warning('插值等式可能无法严格满足 (残差 %.3e). 若要强制满足，可考虑增大 N 或放宽约束。', resnorm);
    % 依使用场景，可视为不可行 or 允许松弛
end
%%
%[text] ## 3 求解过程
%%
%[text] ### （1）最小二乘法求解优化问题
% ---------- 最小二乘基准解（仅供对比） ----------
theta_ls = theta_test;  % 使用前面计算的最小二乘解
fprintf('LS解的插值残差: %.3e\n', resnorm); %[output:959bbd00]

% 计算最小二乘解的H∞性能
mag_ls = abs(G_grid(:) .* (Phi_grid * theta_ls));
gamma_ls = max(mag_ls);
fprintf('LS解的H∞范数: %.6f\n', gamma_ls); %[output:7e15cf4b]
fprintf('LS解的参数范数: %.6f\n', norm(theta_ls)); %[output:8383b08b]
%%
%[text] ### （2）cvx求解优化问题
% ---------- CVX: 直接最小化 gammma，等式作为硬约束 ----------
if exist('cvx_begin','file') ~= 2
    fprintf('CVX 未安装，使用 LS 解。\n');
    theta_opt = theta_ls;
    gammma = gamma_ls;
else
    r0 = 1e4;                     % theta norm bound
    cvx_begin quiet
        cvx_precision high
        variable theta(N,1)
        variable gammma nonnegative
        minimize( gammma )
        subject to
            for i = 1:Nfreq
                abs( G_grid(i) * (Phi_grid(i,:) * theta) ) <= gammma;
            end
            Aeq * theta == beq;
            norm(theta,2) <= r0;
    cvx_end
    theta_opt = theta;
end
%%
%[text] ### （3）最优化问题总结分析
if exist('cvx_begin','file') == 2 %[output:group:018c7a4e]
    theta_opt = theta;
    compare_CVX_LS(gamma_ls, theta_ls, resnorm, gammma, theta_opt, Aeq, beq); %[output:347498aa]
else
    theta_opt = theta_ls;
    fprintf('跳过 CVX 对比（CVX 未安装）。\n');
end %[output:group:018c7a4e]
% dense check validation
Mchk = 3000;
w_chk = linspace(0, pi, Mchk);
G_chk = squeeze(freqresp(G0, w_chk * fs)).';
Phi_chk = zeros(Mchk, N);
for k=1:N, Phi_chk(:,k) = exp(-1j*w_chk*(k-1)); end
mag = abs( G_chk(:) .* (Phi_chk * theta_opt) );
gammma_check = max(mag);
fprintf('CVX gammma = %.6e, dense-grid gammma_check = %.6e, residual ||A theta - b|| = %.3e\n', gammma, gammma_check, norm(A*theta_opt - b)); %[output:26d9d9a3]
%%
%[text] ## 4 抗干扰仿真分析
% 扰动参数
Ts = 1/480;
fs = 1/Ts;
omega0 = w_interp(:); % rad/sample, 25rad/sec
Nsim = 480*50;   % 50秒
t = (0:Nsim-1)*Ts;
d = sum(sin(omega0*t*fs) + 0.02*randn(length(omega0),Nsim),1);
figure('Name', '扰动信号'); %[output:6d085dac]
plot(t, d); grid on; %[output:6d085dac]
xlabel('Time(s)'); ylabel('Magnitude'); %[output:6d085dac]
xlim([0,5]); %[output:6d085dac]
% 构造 FIR 系数（z^-1 顺序）
b_K_cvx = [0; flip(theta_opt(:))]; % CVX优化解
b_K_ls = [0; flip(theta_ls(:))];   % 最小二乘解

% 绘制频率响应对比
nfft = 1024;
[Hk_cvx, fk] = freqz(b_K_cvx, 1, nfft, fs);
[Hk_ls, ~] = freqz(b_K_ls, 1, nfft, fs);

figure('Name', '控制器频率响应对比: CVX vs 最小二乘'); %[output:86e11be7]
subplot(2,1,1);  %[output:86e11be7]
semilogx(fk, 20*log10(abs(Hk_cvx)), 'r-', 'LineWidth', 2, 'DisplayName', 'CVX优化解'); %[output:86e11be7]
hold on; %[output:86e11be7]
semilogx(fk, 20*log10(abs(Hk_ls)), 'b--', 'LineWidth', 2, 'DisplayName', '最小二乘解'); %[output:86e11be7]
xlabel('Frequency (Hz)'); ylabel('Magnitude (dB)'); grid on; %[output:86e11be7]
title('控制器幅频响应对比'); %[output:86e11be7]
legend('Location', 'best'); %[output:86e11be7]
subplot(2,1,2);  %[output:86e11be7]
semilogx(fk, angle(Hk_cvx)*180/pi, 'r-', 'LineWidth', 2, 'DisplayName', 'CVX优化解'); %[output:86e11be7]
hold on; %[output:86e11be7]
semilogx(fk, angle(Hk_ls)*180/pi, 'b--', 'LineWidth', 2, 'DisplayName', '最小二乘解'); %[output:86e11be7]
xlabel('Frequency (Hz)'); ylabel('Phase (deg)'); grid on; %[output:86e11be7]
title('控制器相频响应对比'); %[output:86e11be7]
legend('Location', 'best'); %[output:86e11be7]
% 构造K(z,theta)
% Kz = tf(theta', [1 zeros(1,N-1)], Ts); % 可选
% 闭环仿真 - CVX解
u_cvx = zeros(1,Nsim);
y_cvx = zeros(1,Nsim);
x_cvx = zeros(1,Nsim);
antinoise_cvx = zeros(1,Nsim);

% 闭环仿真 - LS解
u_ls = zeros(1,Nsim);
y_ls = zeros(1,Nsim);
x_ls = zeros(1,Nsim);
antinoise_ls = zeros(1,Nsim);

% 获取G0(z)分子分母系数（z形式）
b = G0.num{1};
a = G0.den{1};

% 控制器仿真
for k = max(N,length(a))+1:Nsim
    if t(k) >= 20
        u_cvx(k) = -sum(theta_opt'.*x_cvx(k-(N:-1:1)));
        u_ls(k) = -sum(theta_ls'.*x_ls(k-(N:-1:1)));
        if isnan(u_cvx(k)), u_cvx(k) = 0; end
        if isnan(u_ls(k)), u_ls(k) = 0; end
    end
    % 离散系统差分方程递推y(k)
    antinoise_cvx(k) = (-a(2:end)*antinoise_cvx(k-1:-1:k-length(a)+1)' + b*u_cvx(k-1:-1:k-length(b))')/a(1);
    antinoise_ls(k) = (-a(2:end)*antinoise_ls(k-1:-1:k-length(a)+1)' + b*u_ls(k-1:-1:k-length(b))')/a(1);
    y_cvx(k) = antinoise_cvx(k) + d(k);
    y_ls(k) = antinoise_ls(k) + d(k);
    x_cvx(k) = y_cvx(k) - antinoise_cvx(k);
    x_ls(k) = y_ls(k) - antinoise_ls(k);
end

% 绘图对比
figure('Name', '控制输入与输出信号对比'); %[output:3c04bf29]
subplot(2,1,1); %[output:3c04bf29]
plot(t, u_cvx, 'r-', 'LineWidth', 1.5, 'DisplayName', 'CVX控制输入'); %[output:3c04bf29]
hold on; %[output:3c04bf29]
plot(t, u_ls, 'b--', 'LineWidth', 1.5, 'DisplayName', 'LS控制输入'); %[output:3c04bf29]
xline(20, 'k:', 'Controller ON','HandleVisibility','off'); %[output:3c04bf29]
xlabel('Time (s)'); ylabel('Control Input u'); %[output:3c04bf29]
title('控制输入信号对比'); %[output:3c04bf29]
legend show; grid on; %[output:3c04bf29]
subplot(2,1,2); %[output:3c04bf29]
plot(t, d, 'k:', 'LineWidth', 1.0, 'DisplayName', 'Disturbance'); %[output:3c04bf29]
hold on; %[output:3c04bf29]
plot(t, y_cvx, 'r-', 'LineWidth', 1.5, 'DisplayName', ['CVX (γ=' num2str(gammma, '%.3f') ')']); %[output:3c04bf29]
plot(t, y_ls, 'b--', 'LineWidth', 1.5, 'DisplayName', ['LS (γ=' num2str(gamma_ls(end), '%.3f') ')']); %[output:3c04bf29]
xline(20, 'k--', 'Controller ON','HandleVisibility','off'); %[output:3c04bf29]
xlabel('Time (s)'); %[output:3c04bf29]
ylabel('Plant output y'); %[output:3c04bf29]
title('闭环输出性能对比: CVX优化 vs 最小二乘'); %[output:3c04bf29]
legend show; grid on; ylim([-2,2]); %[output:3c04bf29]
%%
%[text] ## 5 自适应仿真分析
%[text] 起初，我期望使用2016年专著中书写的成熟的控制方法来进行设计，但是在该书中没有提供完整的控制器设计策略。应对论文中的控制器设计方法，最好还是先从论文复现出发。
%[text] 在TAC2015论文中还没有提出引入一个固定控制器的设计方法，而是直接引入一个参数$\\tau\_{0\\;}${"editStyle":"visual"}作为增益。
rng(42);  % 固定随机种子
d = 0.7*sin(25*t + pi/3) + 0.5*sin(225*t + pi/4);
idx_add = t >= 30;  % step activation
d(idx_add) = d(idx_add) + ...
             0.6*sin(85*t(idx_add) - pi/6) + ...
             0.4*sin(125*t(idx_add) + pi/2);
v = 0.02*randn(size(t));         % std = 0.02
v = max(min(v,0.1),-0.1);        % |v| ≤ 0.1
d = d + v;
N = 50;
% ---------- 1. F(z) 滤波器 ----------
% 注: G0(z) 在扰动频段增益仅 -73~-58dB, 纯延迟基自适应控制器在此条件下
% 无法获得有效抑制 (详见 DebugReport_JafariJVC_Discrete.md §5.2).
% 此处保留 F=100 静态增益作教学对照, 正确方案 (Lambda基+F(s)频谱平坦化)
% 参考 demo3_Robust\demos\Jafari_AdaptiveCC_Fixed.m
F_gain = 100;
b_F = F_gain;
a_F = 1;

% ---------- 2. 初始化自适应仿真变量 ----------
% 关键信号
kz_adapt = zeros(1,Nsim);
antinoise_term = zeros(1,Nsim);
u_adapt = zeros(1,Nsim);
y_adapt = zeros(1,Nsim);
z_adapt = zeros(1,Nsim); % 观测信号 z = y - G0*u
ep_adapt = zeros(1, Nsim);
phi_hist = zeros(N,1);    % 回归向量

% 自适应参数
theta_adapt = zeros(N,1); % 参数初值为0
P = eye(N) * 100;         % 协方差矩阵 P(0)=100I (适度增大以适应参数尺度)
gamma0 = 1;               % 归一化增益
theta_max = 100;           % 投影界 (F_gain=100 补偿 G0 低增益，θ 约需 12–50)

% 历史缓冲区 (用于IIR滤波器)
hist_len = max([length(a), length(b)]) + N + 1;
phi_G0_u_hist = zeros(1, length(b));
phi_G0_y_hist = zeros(1, length(a));
phi_N = zeros(1, Nsim);
F_u_hist = zeros(1, length(b_F));
F_y_hist = zeros(1, length(a_F));

% 监控变量
theta_history = zeros(N, Nsim);
rms_history = zeros(1, Nsim);

% ---------- 3. 自适应控制仿真循环 ----------
% phi_adpat   N×1
% theta_adpat N×1
for k = hist_len:Nsim
    % --- 步骤1: 计算系统输出 y(k) ---
    % y(k) = G(u(k-1)) + d(k)，这里假设 G=G0
    % 使用差分方程直接计算
    antinoise_term(k) = (-a(2:end)*antinoise_term(k-1:-1:k-length(a)+1)' + b*u_adapt(k-1:-1:k-length(b))')/a(1);
    y_adapt(k) = antinoise_term(k) + d(k);
    
    if t(k) >= 20  % 20秒后开启自适应控制
        % --- 步骤2: 计算观测信号 z(k) ---
        % z(k) = y(k) - G0(u(k-1))
        % G0(u(k-1))与上面计算的antinoise_term是同一个值
        z_adapt(k) = y_adapt(k) - antinoise_term(k);

        % --- 步骤3: 回归量 phi = F * G0[z_delays] (F=100 静态增益)
        [phi_N(k), phi_G0_u_hist, phi_G0_y_hist] = IIR_filter(b, a, z_adapt(k), phi_G0_u_hist, phi_G0_y_hist);
        phi_hist = F_gain * phi_N(k-(N:-1:1)+1)';

        % --- 步骤4: 更新自适应参数 theta(k) ---
        % 归一化RLS + 参数投影
        m_s_squared = 1 + gamma0 * (phi_hist' * phi_hist);
        epsilon = (z_adapt(k) - theta_adapt' * phi_hist) / m_s_squared;
        ep_adapt(k) = epsilon;
        P_phi = P * phi_hist;
        denom = m_s_squared + phi_hist' * P_phi;
        K_rls = P_phi / denom; % Kalman增益
        P = P - (K_rls * P_phi');
        theta_new = theta_adapt + K_rls * epsilon;  % 修复: 用Kalman增益
        th_n = norm(theta_new);
        if th_n > theta_max, theta_adapt = theta_new * theta_max/th_n;
        else, theta_adapt = theta_new; end

        % --- 步骤5: 控制 u = -F * theta' * z_delays (F=100 静态增益)
        z_delays = z_adapt(k-(N:-1:1)+1)';
        K_z_k = theta_adapt' * z_delays;
        kz_adapt(k) = K_z_k;
        u_adapt(k) = -F_gain * K_z_k;
    else
        % 控制器关闭时，系统自由响应
        z_adapt(k) = y_adapt(k); % z=y
        u_adapt(k) = 0;
    end
    
    % 记录历史数据
    theta_history(:,k) = theta_adapt;
    if k > fs
        window_start = max(1, k - fs + 1);
        rms_history(k) = rms(y_adapt(window_start:k));
    end
end

% ---------- 4. 性能分析与可视化 ----------
% 自适应控制性能对比
figure('Name', '自适应(Jafari结构) vs 固定MOSEK控制器'); %[output:58809802]
subplot(3,1,1); %[output:58809802]
hold on; %[output:58809802]
plot(t, y_adapt, 'b', 'LineWidth', 1.5, 'DisplayName', '自适应 (Jafari)'); %[output:58809802]
plot(t, d, 'k:', 'LineWidth', 1.0, 'DisplayName', '扰动信号'); %[output:58809802]
xline(20, 'g--', 'Controller ON'); %[output:58809802]
xlabel('Time (s)'); ylabel('Output y'); %[output:58809802]
title('输出性能对比'); %[output:58809802]
legend show; grid on; ylim([-2,2]); %[output:58809802]

subplot(3,1,2); %[output:58809802]
hold on; %[output:58809802]
plot(t, u_adapt, 'b--', 'LineWidth', 1.5, 'DisplayName', '自适应 (Jafari)'); %[output:58809802]
xline(20, 'g--', 'Controller ON'); %[output:58809802]
xlabel('Time (s)'); ylabel('Control Input u'); %[output:58809802]
title('控制输入对比'); %[output:58809802]
legend show; grid on; %[output:58809802]

subplot(3,1,3); %[output:58809802]
plot(t, rms_history, 'b-', 'LineWidth', 1.5); %[output:58809802]
xline(20, 'g--', 'Controller ON'); %[output:58809802]
xlabel('Time (s)'); ylabel('Rolling RMS'); %[output:58809802]
title('自适应控制RMS收敛轨迹'); %[output:58809802]
grid on; %[output:58809802]

% 参数演化对比
figure('Name', '控制器参数演化对比: MOSEK vs 自适应(Jafari)'); %[output:5ccdadd7]
param_indices = [1, 5, 10, 15];
colors = {'r-', 'g-', 'b-', 'm-'};
for i = 1:length(param_indices) %[output:group:13665faf]
    subplot(2,2,i); %[output:5ccdadd7]
    idx = param_indices(i);
    plot(t, repmat(theta_opt(idx), 1, Nsim), 'k--', 'LineWidth', 2, 'DisplayName', sprintf('MOSEK θ_%d', idx));
    hold on;
    plot(t, theta_history(idx,:), colors{i}, 'LineWidth', 1.5, 'DisplayName', sprintf('自适应 θ_%d', idx));
    xline(20, 'g--', 'Controller ON', 'Alpha', 0.7);
    xlabel('Time (s)'); ylabel(sprintf('θ_%d', idx));
    title(sprintf('参数 θ_%d 演化', idx));
    legend('Location', 'best'); grid on;
end %[output:group:13665faf]

% 所有参数的范数演化
figure('Name', '控制器参数范数演化 (Jafari)'); %[output:72acd940]
theta_norm_history = sqrt(sum(theta_history.^2, 1));
plot(t, theta_norm_history, 'b-', 'LineWidth', 1.5, 'DisplayName', '自适应参数范数'); %[output:72acd940]
hold on; %[output:72acd940]
plot(t, repmat(norm(theta_opt), 1, Nsim), 'r--', 'LineWidth', 2, ... %[output:72acd940]
     'DisplayName', sprintf('MOSEK参数范数 = %.4f', norm(theta_opt))); %[output:72acd940]
xline(20, 'g--', 'Controller ON'); %[output:72acd940]
xlabel('Time (s)');  %[output:72acd940]
ylabel('||θ||_2'); %[output:72acd940]
title('控制器参数范数演化对比'); %[output:72acd940]
legend('Location', 'best');  %[output:72acd940]
grid on; %[output:72acd940]
figure; %[output:3aa68815]
plot(t, rms_history, 'LineWidth',1.5); grid on; %[output:3aa68815]
xlabel('Time (s)'); ylabel('RMS(y)'); %[output:3aa68815]
title('Rolling RMS of output'); %[output:3aa68815]

% ---- 性能统计 ----
rms_d_s5 = rms(d(20*fs:end));
rms_adapt_s5 = rms(y_adapt(20*fs:end));
fprintf('\n--- 自适应控制性能统计 (第5节) ---\n'); %[output:5feeea7f]
fprintf('扰动RMS: %.4f\n', rms_d_s5); %[output:87caf167]
fprintf('自适应控制后RMS: %.4f (抑制 %.1f dB)\n', rms_adapt_s5, 20*log10(rms_d_s5/rms_adapt_s5)); %[output:26a40f03]
%%
%[text] ## 6 结构鲁棒性测试：从回归量中移除 G₀(z)
%[text] **对照实验**：使用 φ = τ₀·w(k) 作为回归量（不含 G₀(z) 滤波），
%[text] 验证 G₀ 滤波的不可或缺性。**预期结果：抑制 ≈ 0 dB**——
%[text] 证明移除 G₀ 后 RLS 无法学习逆对象动态，自适应算法失效。
%% 1. 系统定义 (含不确定性)
clear G0 z S T
Ts = 1/480;  z = tf('z', Ts);  fs = 1/Ts;
G0_tf = (-0.00146*(z-0.1438)*(z+1)) / ((z - 0.7096)*(z^2 - 0.04369*z + 0.01392));
[num0, den0] = tfdata(G0_tf, 'v');
Delta_m = -0.0001 / (z + 0.99)^2;
G_true_tf = G0_tf * (1 + Delta_m);
[num_true, den_true] = tfdata(G_true_tf, 'v');

%% 2. 仿真参数 (专著 Table 4.1)
T_end = 50;  Nsim6 = T_end*fs;  t6 = (0:Nsim6-1)'*Ts;
% 多频扰动 + 30s阶跃
d1 = 0.7*sin(25*t6 + pi/3) + 0.5*sin(225*t6 + pi/4);
d2 = 0.6*sin(85*t6 - pi/6) + 0.4*sin(125*t6 + pi/2);
idx_30s6 = find(t6 >= 30, 1);
d_total6 = d1;  d_total6(idx_30s6:end) = d_total6(idx_30s6:end) + d2(idx_30s6:end);
rng(42);  v6 = 0.02*randn(Nsim6, 1);  v6 = max(min(v6, 0.1), -0.1);
d_total6 = d_total6 + v6;

N6 = 50;  tau0 = 10;  c0 = 1;
P0_val = 500;  P6 = P0_val * eye(N6);
theta_max = 10;  theta6 = zeros(N6, 1);

%% 3. 初始化
y6 = zeros(Nsim6,1);  u6 = zeros(Nsim6,1);
zeta_hist6 = zeros(Nsim6,1);
nG0 = max(length(num0), length(den0))-1;
nG = max(length(num_true), length(den_true))-1;
G_state6 = zeros(nG,1);  G0_state_zeta6 = zeros(nG0,1);
buffer_zeta6 = zeros(N6,1);  u_prev6 = 0;

fprintf('\n===== 结构测试: phi = tau0*w (无 G0 滤波) =====\n'); %[output:1503ef2f]

%% 4. 仿真循环
for k = 1:Nsim6
    [y_no_d6, G_state6] = filter(num_true, den_true, u_prev6, G_state6);
    y6(k) = y_no_d6 + d_total6(k);
    [G0_u6, G0_state_zeta6] = filter(num0, den0, u_prev6, G0_state_zeta6);
    zeta_k6 = y6(k) - G0_u6;  zeta_hist6(k) = zeta_k6;

    u_current6 = 0;
    if t6(k) >= 10
        w_vec6 = flipud(buffer_zeta6);
        phi_vec6 = tau0 * w_vec6;  % phi = tau0*w (不含 G0 滤波)

        pred_err6 = zeta_k6 - theta6' * phi_vec6;
        m2_6 = 1 + c0 * (phi_vec6' * phi_vec6);
        epsilon6 = pred_err6 / m2_6;
        P_phi6 = P6 * phi_vec6;
        denom6 = m2_6 + phi_vec6' * P_phi6;
        if denom6 > 1e-12
            Kgain6 = P_phi6 / denom6;  % Kalman 增益
            P6 = P6 - (Kgain6 * P_phi6');
            theta_new6 = theta6 + Kgain6 * pred_err6;  % 使用 Kalman 增益 × 预测误差
        else
            theta_new6 = theta6;
        end
        if norm(theta_new6) > theta_max
            theta_new6 = theta_new6 * (theta_max / norm(theta_new6));
        end
        theta6 = theta_new6;

        u_current6 = -tau0 * (theta6' * w_vec6);
        u_current6 = max(min(u_current6, 100), -100);
    end

    u6(k) = u_current6;  u_prev6 = u6(k);
    buffer_zeta6 = [zeta_k6; buffer_zeta6(1:end-1)];
end

%% 5. 性能报告
idx1_6 = (t6>20 & t6<30);  idx2_6 = (t6>40 & t6<50);
rms_d1_6 = rms(d_total6(idx1_6));  rms_y1_6 = rms(y6(idx1_6));
supp1_6 = 20*log10(rms_d1_6/rms_y1_6);  % 正值=降噪
rms_d2_6 = rms(d_total6(idx2_6));  rms_y2_6 = rms(y6(idx2_6));
supp2_6 = 20*log10(rms_d2_6/rms_y2_6);

fprintf('\n========== 结构测试结果 (预期 ~0 dB, 验证 G0 滤波必要性) ==========\n'); %[output:2e846088]
fprintf('阶段1 (20-30s): 抑制=%.1f dB, u_RMS=%.2f\n', supp1_6, rms(u6(idx1_6))); %[output:73956e02]
fprintf('阶段2 (40-50s): 抑制=%.1f dB, u_RMS=%.2f\n', supp2_6, rms(u6(idx2_6))); %[output:2f66e010]
fprintf('抑制≈0 dB 为预期结果: 移除 G0 滤波后 RLS 无法学习逆对象动态\n'); %[output:64e48bf4]
fprintf('||theta||=%.3f, tr(P)=%.2e\n', norm(theta6), trace(P6)); %[output:64e48bf4]

% ---- 图: 结构鲁棒性测试 ----
figure('Name','结构鲁棒性测试'); %[output:51c6a242]
subplot(3,1,1); %[output:51c6a242]
plot(t6, d_total6, 'Color',[0.7 0.7 0.7]); hold on; %[output:51c6a242]
plot(t6, y6, 'b-', 'LineWidth',1); %[output:51c6a242]
xline(10,'r--','Control ON'); xline(30,'r--','New Disturbance'); %[output:51c6a242]
ylabel('Amplitude'); title(sprintf('输出信号 (S1: %.1f dB, S2: %.1f dB)', supp1_6, supp2_6)); grid on; %[output:51c6a242]
legend('d(t)', 'y(t)'); %[output:51c6a242]

subplot(3,1,2); %[output:51c6a242]
plot(t6, u6, 'g-', 'LineWidth',1); %[output:51c6a242]
xline(10,'r--'); xline(30,'r--'); %[output:51c6a242]
ylabel('Control u'); title('控制信号'); grid on; %[output:51c6a242]

subplot(3,1,3); %[output:51c6a242]
plot(t6, zeta_hist6, 'k-', 'LineWidth',1); %[output:51c6a242]
xline(10,'r--'); xline(30,'r--'); %[output:51c6a242]
xlabel('Time (s)'); ylabel('zeta(t)'); title('观测信号 zeta(t) = y - G_0[u]'); grid on; %[output:51c6a242]
%%
%[text] ## 附录
function compare_CVX_LS(gamma_ls, theta_ls, resnorm, gammma, theta_opt, Aeq, beq)
    fprintf('\n--- CVX vs 最小二乘解法对比 ---\n');
    fprintf('方法          | H∞范数    | 参数范数   | 插值残差\n');
    fprintf('-------------|----------|----------|----------\n');
    fprintf('最小二乘(LS) | %.6f | %.6f | %.3e\n', gamma_ls, norm(theta_ls), resnorm);
    fprintf('CVX优化     | %.6f | %.6f | %.3e\n', gammma, norm(theta_opt), norm(Aeq*theta_opt - beq));

    % 性能改善分析
    improvement_ratio = gamma_ls / gammma;
    fprintf('\nCVX相对LS的H∞性能改善: %.2f倍\n', improvement_ratio);
    if improvement_ratio > 1.2
        fprintf('✓ CVX优化显著改善了H∞性能\n');
    elseif improvement_ratio > 1.05
        fprintf('△ CVX优化略有改善H∞性能\n'); 
    else
        fprintf('○ CVX与LS性能接近，可能H∞约束不起作用\n');
    end
end

